const crypto = require('crypto');
const expected = Buffer.from($env.DOC_UPLOAD_TOKEN ?? '');
const given = Buffer.from(String($json.headers['x-upload-token'] ?? ''));
const valid = expected.length > 0 && given.length === expected.length && crypto.timingSafeEqual(given, expected);
// keep the uploaded file: a Code node that returns only json drops binary data
return { json: { ...$json, valid }, binary: $input.item.binary };

// One output item per PDF, whatever the source. Binary is renamed to "file".
const out = [];
$input.all().forEach((item, i) => {
  const j = item.json;
  const isUpload = Boolean(j.headers);
  for (const [key, bin] of Object.entries(item.binary ?? {})) {
    const isPdf = (bin.mimeType ?? '').includes('pdf') || /\.pdf$/i.test(bin.fileName ?? '');
    if (!isPdf) continue;
    out.push({
      json: {
        source: isUpload ? 'upload' : 'email',
        emailMessageId: isUpload ? null : j.id ?? null,
        emailFrom: isUpload ? null : j.from?.value?.[0]?.address ?? j.from?.text ?? null,
        subject: j.subject ?? null,
        fileName: bin.fileName ?? key + '.pdf',
        mimeType: 'application/pdf',
      },
      binary: { file: bin },
      pairedItem: { item: i },
    });
  }
});
return out;

const crypto = require('crypto');
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'file');
  out.push({
    json: {
      ...items[i].json,
      sha256: crypto.createHash('sha256').update(buf).digest('hex'),
      sizeBytes: buf.length,
      base64: buf.toString('base64'), // reused for the LLM call and the Odoo attachment
    },
    binary: items[i].binary,
    pairedItem: { item: i },
  });
}
return out;

