const v = $('Validate & Route').item.json;
const doc = $('Hash File').item.json;
const t = $('Create Review Token').item.json;
const reviewId = $('Add to Review Queue').item.json.review_id;
const inv = v.invoice ?? {};
const esc = (s) => String(s ?? '-').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const eur = (n) => (n == null ? '-' : Number(n).toLocaleString('de-DE', { minimumFractionDigits: 2 }) + ' EUR');
const link = (decision) => $env.WEBHOOK_URL + 'webhook/review-decision?id=' + reviewId + '&token=' + t.token + '&decision=' + decision;
const canApprove = Boolean(inv.supplier_name && inv.invoice_number && inv.total_amount != null && (inv.line_items ?? []).length);
return { json: {
  subject: 'Rechnung prüfen / Invoice needs review: ' + (inv.supplier_name || doc.fileName),
  html: [
    '<h3>Rechnung prüfen / Invoice needs review</h3>',
    '<p>Document #' + v.documentId + ' (' + esc(doc.fileName) + ', from ' + esc(doc.source) + ') was not booked automatically.</p>',
    '<p><b>Problems:</b></p><ul>' + t.reasons.map((r) => '<li>' + esc(r) + '</li>').join('') + '</ul>',
    '<table cellpadding="4">',
    '<tr><td><b>Supplier</b></td><td>' + esc(inv.supplier_name) + '</td></tr>',
    '<tr><td><b>Invoice no.</b></td><td>' + esc(inv.invoice_number) + '</td></tr>',
    '<tr><td><b>Date</b></td><td>' + esc(inv.invoice_date) + '</td></tr>',
    '<tr><td><b>Net / VAT / Total</b></td><td>' + eur(inv.net_amount) + ' / ' + eur(inv.vat_amount) + ' / ' + eur(inv.total_amount) + '</td></tr>',
    '<tr><td><b>Confidence</b></td><td>' + v.confidence + '</td></tr>',
    '</table>',
    '<p>',
    canApprove ? '<a href="' + link('approve') + '">✅ Approve – create draft bill in Odoo / Freigeben</a> &nbsp; ' : '',
    '<a href="' + link('reject') + '">❌ Reject / Ablehnen</a>',
    '</p>',
    '<p style="color:#666">Review item #' + reviewId + '. Links open a confirmation page and can be used once.</p>',
  ].join('\n'),
} };

